import{_ as e,o as r,c as o,a0 as t}from"./chunks/framework.BGyYNsHo.js";const p=JSON.parse('{"title":"Estructuras hidráulicas y condiciones de borde","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/hidraulica/10-estructuras-y-condiciones-de-borde.md","filePath":"es/explanation/hidraulica/10-estructuras-y-condiciones-de-borde.md"}'),i={name:"es/explanation/hidraulica/10-estructuras-y-condiciones-de-borde.md"};function d(n,a,s,c,l,u){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="estructuras-hidraulicas-y-condiciones-de-borde" tabindex="-1">Estructuras hidráulicas y condiciones de borde <a class="header-anchor" href="#estructuras-hidraulicas-y-condiciones-de-borde" aria-label="Permalink to &quot;Estructuras hidráulicas y condiciones de borde&quot;">​</a></h1><h2 id="estructuras-hidraulicas-no-conducto" tabindex="-1">Estructuras hidráulicas no-conducto <a class="header-anchor" href="#estructuras-hidraulicas-no-conducto" aria-label="Permalink to &quot;Estructuras hidráulicas no-conducto&quot;">​</a></h2><p>Los caudales de las estructuras no-conducto los calcula <code>HydStructures.cpp</code> (<code>StructureSolver</code>) dentro de la iteración de Picard de la onda dinámica, un enlace a la vez en orden de índice (para que dos bombas que comparten una cámara húmeda se vean mutuamente la extracción), con distribución inmediata en los acumuladores de los nodos y subrelajación a $\\omega = 0.5$ para iteraciones $&gt; 0$ (las bombas quedan exentas).</p><h3 id="bombas" tabindex="-1">Bombas <a class="header-anchor" href="#bombas" aria-label="Permalink to &quot;Bombas&quot;">​</a></h3><p>El control de arranque/parada de las bombas usa histéresis de tirante aplicada una vez por paso de tránsito:</p><p>$$\\text{detener si } d &lt; d_{\\mathrm{off}} \\ (\\text{regulación} &gt; 0), \\qquad \\text{arrancar si } d &gt; d_{\\mathrm{on}} \\ (\\text{regulación} = 0).$$</p><p>Los tipos de curva de bomba (1–5) determinan el caudal $q$ a partir de la curva versus el volumen de la cámara húmeda (tipo 1), el tirante (tipos 2 y 4) o la carga (tipos 3 y 5, donde $q$ se escala por la regulación de velocidad $s$ y la carga por $s^2$); una bomba ideal descarga exactamente el ingreso más el rebalse del nodo aguas arriba. La limitación de caudal (legado <code>getModPumpFlow</code>) evita bombear más de lo disponible (protección contra aspiración en seco) y, para bombas tipo 1 o alimentadas por estanque, acota $q$ por $Q_{\\mathrm{in}} + V_{\\mathrm{old}}/\\Delta t$.</p><h3 id="orificios" tabindex="-1">Orificios <a class="header-anchor" href="#orificios" aria-label="Permalink to &quot;Orificios&quot;">​</a></h3><p>Los orificios de fondo y laterales usan un coeficiente y un tirante crítico definidos a partir de la altura de apertura $h_{\\mathrm{open}} = s,y_{\\mathrm{full}}$ (regulación $s$):</p><p>$$ \\begin{aligned} f &amp;= \\min!\\left(\\frac{\\text{carga}}{h_{\\mathrm{crit}}},\\ 1\\right), \\qquad h_{\\mathrm{crit}} = \\frac{C_d}{0.414},\\frac{h_{\\mathrm{open}}} {4}\\ \\text{(circular)}\\ \\text{o}\\ \\frac{C_d}{0.414}, \\frac{h_{\\mathrm{open}},W_{\\max}}{2(h_{\\mathrm{open}} + W_{\\max})} \\text{(rectangular)},\\ q &amp;= \\begin{cases} C_w,f^{3/2} &amp; f &lt; 1 \\quad\\text{(escurrimiento parcial tipo vertedero)},\\ C_d,A_{\\mathrm{eff}}\\sqrt{2g,H} &amp; f \\ge 1 \\quad\\text{(orificio lleno)}, \\end{cases} \\end{aligned} $$</p><p>con $C_w = C_d\\sqrt{h_{\\mathrm{crit}}},A_{\\mathrm{eff}}\\sqrt{2g}$ (coeficiente de vertedero de cresta afilada 0.414), $A_{\\mathrm{eff}}$ el área de la sección transversal a la altura de apertura y $H$ la carga apropiada (carga diferencial cuando está sumergido/ahogado). El gradiente de caudal es</p><p>$$\\frac{dQ}{dH} = \\frac{3}{2},\\frac{q}{f,h_{\\mathrm{crit}}} \\quad\\text{(régimen vertedero)}, \\qquad \\frac{dQ}{dH} = \\frac{q}{2H} \\quad\\text{(régimen orificio)}.$$</p><p>Puede aplicarse una pérdida de carga opcional de compuerta de retención ARMCO y la corrección de sumersión de Villemonte.</p><h3 id="vertederos" tabindex="-1">Vertederos <a class="header-anchor" href="#vertederos" aria-label="Permalink to &quot;Vertederos&quot;">​</a></h3><p>Los cuatro tipos de vertedero (transversal, lateral, escotadura en V, trapezoidal) descargan según</p><p>$$ \\begin{aligned} q &amp;= C_d,L,h^{3/2} &amp;&amp;\\text{(transversal)},\\ q &amp;= C_d,L^{0.83},h^{1.67} &amp;&amp;\\text{(lateral, corregido)},\\ q &amp;= C_d,s_h,h^{5/2} &amp;&amp;\\text{(escotadura en V)}, \\end{aligned} $$</p><p>con contracciones de extremo que reducen la longitud efectiva. Cuando la línea de gradiente hidráulica aguas arriba alcanza la clave ($H_1 \\ge H_{\\mathrm{crown}}$) y se permite la entrada en carga, el vertedero transita a escurrimiento por orificio usando un coeficiente equivalente de orificio calculado desde el caudal del vertedero a apertura completa:</p><p>$$C_{\\mathrm{sur}} = \\frac{Q_{\\mathrm{weir}}(s,y_{\\mathrm{full}})} {\\sqrt{(s,y_{\\mathrm{full}})/2}}, \\qquad q = C_{\\mathrm{sur}}\\sqrt{H_{\\mathrm{orif}}},$$</p><p>con $H_{\\mathrm{orif}}$ la carga al punto medio de la abertura (o la carga diferencial cuando está sumergido/ahogado). Si no se permite la entrada en carga, la carga se acota en la clave y se mantiene la ecuación de vertedero. La corrección de sumersión de Villemonte se aplica cuando la LGH aguas abajo supera la cresta. La contribución de área superficial del vertedero se anula por compatibilidad con SWMM 4.</p><h3 id="descargas-outlets" tabindex="-1">Descargas (outlets) <a class="header-anchor" href="#descargas-outlets" aria-label="Permalink to &quot;Descargas (outlets)&quot;">​</a></h3><p>Las descargas usan curvas de gasto en función de la carga o del tirante (tabulares o funcionales):</p><p>$$q = C,H^{e} \\quad\\text{(funcional)}, \\qquad q = \\mathrm{table}(H) \\quad\\text{(tabular)},$$</p><p>escaladas por la regulación. El $dQ/dH$ se deja deliberadamente en cero (igual que el legado), lo que evita inflar el denominador de carga de los nodos.</p><h2 id="condiciones-de-borde-de-emisario" tabindex="-1">Condiciones de borde de emisario <a class="header-anchor" href="#condiciones-de-borde-de-emisario" aria-label="Permalink to &quot;Condiciones de borde de emisario&quot;">​</a></h2><p>Los niveles de agua de los emisarios se fijan al inicio de cada paso de tránsito y nuevamente dentro de cada iteración de Picard a partir de los caudales actuales de los conductos. Para el conducto conectado a un emisario en un extremo de elevación $z$, con caudal por barril $q$, se calculan el tirante normal $y_n$ (desde el factor de sección inverso) y el tirante crítico $y_c$ ($y_c$ tiene formas cerradas para las formas estándar y una búsqueda numérica de raíz en el resto). El nivel depende del tipo de condición de borde (<code>Outfall.cpp:setOutfallDepth</code>):</p><ul><li><strong>LIBRE (FREE)</strong>: caída libre, $d = z + \\min(y_n, y_c)$.</li><li><strong>NORMAL</strong>: $d = z + y_n$.</li><li><strong>FIJO (FIXED)</strong>, <strong>MAREA (TIDAL)</strong>, <strong>SERIE DE TIEMPO (TIMESERIES)</strong>: el nivel $s_{\\mathrm{stage}}$ es constante, proviene de una tabla de mareas (hora del día) o de una serie de tiempo; entonces</li></ul><p>$$d = \\begin{cases} s_{\\mathrm{stage}} - z_{\\mathrm{inv}} &amp; z + y_c + z_{\\mathrm{inv}} &lt; s_{\\mathrm{stage}},\\ \\max(0,\\ s_{\\mathrm{stage}} - z_{\\mathrm{inv}}) &amp; z &gt; 0 \\wedge s_{\\mathrm{stage}} &lt; z_{\\mathrm{inv}} + z,\\ z + y_c &amp; z &gt; 0 \\wedge s_{\\mathrm{stage}} \\ge z_{\\mathrm{inv}} + z,\\ y_c &amp; z = 0. \\end{cases}$$</p><p>El último caso mantiene un emisario fijo de descarga libre al tirante crítico del conducto. Una compuerta de retención en un emisario bloquea el flujo inverso.</p><h2 id="divisores-de-flujo" tabindex="-1">Divisores de flujo <a class="header-anchor" href="#divisores-de-flujo" aria-label="Permalink to &quot;Divisores de flujo&quot;">​</a></h2><p>Los divisores están activos solo bajo tránsito por onda cinemática (y permanente); bajo onda dinámica actúan como cámaras de unión ordinarias. Dado el ingreso total $Q_{\\mathrm{in}}$ en el nodo divisor:</p><ul><li><strong>De corte (cutoff)</strong>: desvía todo el ingreso sobre un mínimo, $Q_{\\mathrm{div}} = \\max(0, Q_{\\mathrm{in}} - q_{\\min})$.</li><li><strong>De rebalse (overflow)</strong>: desvía el ingreso sobre la capacidad del enlace de continuación.</li><li><strong>Tabular</strong>: $Q_{\\mathrm{div}} = Q_{\\mathrm{in}}\\cdot f(Q_{\\mathrm{in}})$ con la fracción de una tabla de gasto.</li><li><strong>Vertedero</strong>: $Q_{\\mathrm{div}} = C_d,W,d^{3/2}$ a partir de una relación de vertedero sobre el tirante del nodo, acotada al ingreso.</li></ul><p>El caudal desviado se escribe en el enlace de desvío; el enlace de continuación lleva el resto.</p>',32)])])}const h=e(i,[["render",d]]);export{p as __pageData,h as default};
